window.AUTH=window.AUTH||{};window.AUTH["17-530"]={"d":"17-530","id":"2017/17-530","n":"Wisconsin Central Ltd. v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioners Wisconsin Central Ltd., et al.","date":"2018-02-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-530/35666/20180216125406314_17-530%20Brief%20for%20Petitioners%20as%20filed.pdf","side":"pet","n":65},{"k":"respondent","label":"Brief of respondent United States","date":"2018-03-19","url":"https://www.supremecourt.gov/DocketPDF/17/17-530/39395/20180319190851287_17-530bsUnitedStates.pdf","side":"res","n":79},{"k":"reply","label":"Reply of petitioners Wisconsin Central Ltd., et al.","date":"2018-04-03","url":"https://www.supremecourt.gov/DocketPDF/17/17-530/42078/20180403122825743_No.%2017-530%20Reply%20Brief%20for%20Petitioners%20FINAL.pdf","side":"pet","n":46}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"137 S. Ct. 1652","y":2017,"id":"2016/16-74","sc":1,"sum":"The Court determined that the “church plan” exemption of the Employee Retirement Income Security Act of 1974 (ERISA) applies to plans that are maintained by a qualifying church-affiliated organization, even if that organization did not originally establish the plan.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Alton R.R. Co. v. R.R. Ret. Bd.","cite":"16 F. Supp. 955","y":1936,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./16/955/","by":{"0":"8, 42","1":"4"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"BNSF Ry. Co. v. United States","cite":"775 F.3d 743","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/775/743/","ar":1,"by":{"0":"29","1":"passim"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"0":"45, 48"}},{"t":"case","label":"Burlington N. & Santa Fe Ry. Co. v. White","cite":"548 U.S. 53","y":2006,"id":"2005/05-259","sc":1,"sum":"In a decision authored by Justice Stephen Breyer and joined by Chief Justice Roberts and six other justices, the Court held that in order to prevail on a claim of retaliatory discrimination, \"a plaintiff must show that a reasonable employee would have found the challenged action materially adverse, which in this context means it well might have dissuaded a reasonable worker from making or supporting a charge of discrimination.\" (internal citations omitted) Justice Samuel Alito wrote separately, agreeing with the result but arguing that the test adopted by the other members of the Court would eventually prove problematic.","sumSrc":"Oyez","by":{"0":"42","1":"49"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"0":"21, 34","2":"13"}},{"t":"case","label":"Chevron U.S.A., Inc. v. NRDC","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":"14, 48","1":"8, 48"}},{"t":"case","label":"Chicago & N.W. Ry. Co. v. United Transp. Union","cite":"402 U.S. 570","y":1971,"id":"1970/189","sc":1,"ar":1,"sum":"Petitioner railroad brought this suit (after formal procedures of the Railway Labor Act had been exhausted) to enjoin a threatened strike by respondent Union, charging that the Union had failed to perform its obligations under § 2 First of the Railway Labor Act \"to exert every reasonable effort to make and maintain agreements concerning rates of pay, rules, and working conditions.\" The Union answered that the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Commissioner v. LoBue","cite":"351 U.S. 243","y":1956,"id":"1955/373","sc":1,"ar":2,"sum":"Under the Internal Revenue Code of 1U39, as amended, the resulting gain to the employee was taxable as income received at the time he exercised the option and purchased the stock, and his taxable gain should be measured as of the time when the options were exercised and not as. of the time when they were granted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"24","2":"7"}},{"t":"case","label":"Commissioner v. Soliman","cite":"506 U.S. 168","y":1993,"id":"1992/91-998","sc":1,"sum":"During the 1983 tax year, respondent Soliman, an anesthesiologist, spent 30 to 35 hours per week administering anesthesia and postoperative care in three hospitals, none of which provided him with an office. He also spent two to three hours per day in a room in his home that he used exclusively as an office, where he did not meet patients but did perform a variety of tasks related to his medical practice. His …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","2":"4"}},{"t":"case","label":"Conn. Nat. Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32, 48"}},{"t":"case","label":"Emery Bird Thayer Dry Goods Co. v. Williams","cite":"107 F.2d 965","y":1939,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/107/965/","by":{"0":"22"}},{"t":"case","label":"Helvering v. Credit Alliance Corp.","cite":"316 U.S. 107","y":1942,"id":"scdb/1941-130","sc":1,"sum":"1. Under § 27 (f) of the Revenue Act of 1930, a distribution in liquidation of surplus accumulated since February 28, 1913, is to be treated, in computing the dividends-paid credit for the purpose of the tax imposed by § 14 on undistributed net income, as a taxable dividend paid. P. 110. So held although, under § 112 (b) (6), the distribution resulted in no gain or loss to the distributee for tax purposes; and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 25","1":"24","2":"7"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"43, 47","2":"18"}},{"t":"case","label":"Hisquierdo v. Hisquierdo","cite":"439 U.S. 572","y":1979,"id":"1978/77-533","sc":1,"sum":"Benefits payable under the Act may not be divided under the community property law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9","1":"2, 4, 43, 45, 46"}},{"t":"case","label":"Houston & Texas Central Railroad Co. v. Texas","cite":"177 U.S. 66","y":1900,"id":"scdb/1899-155","sc":1,"sum":"The Federal character of a suit must appear in the plaintiffs own statement of his claim, and where a defence has been interposed, the reply to which brings out matters of a Federal nature, those matters thus brought out by the plaintiff do not form-a part of his cause of action.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22","2":"5"}},{"t":"case","label":"Lamie v. U.S. Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Michigan v. EPA","cite":"135 S. Ct. 2699","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2699/","sc":1,"by":{"0":"48, 49","2":"23"}},{"t":"case","label":"N. Haven Bd. of Educ. v. Bell","cite":"456 U.S. 512","y":1982,"id":"1981/80-986","sc":1,"sum":"The Court held that, while Title IX does not expressly include employees, Congress’s choice of words, i.e. “no person” as opposed to “student” or “beneficiary”, implies an intention to broadly cover individuals involved in educational institutions rather than only students.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"N.J. Transit Policemen’s Benev. Ass’n v. N.J. Transit Corp.","cite":"806 F.2d 451","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/806/451/","by":{"0":"40"}},{"t":"case","label":"Nat’l Ass’n of Home Builders v. Defs. of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"sum":"The majority opinion held that Section 7(a)(2)'s provisions for protecting endangered species do not establish a \"tenth criterion\" for the EPA to consider before transferring permitting authority.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Nestle Holdings v. Commissioner of Internal Revenue","cite":"94 T.C. 803","y":1990,"url":"https://www.courtlistener.com/c/T.C./94/803/","by":{"0":"25, 33"}},{"t":"case","label":"Posadas v. Nat’l City Bank of N.Y.","cite":"296 U.S. 497","y":1936,"id":"scdb/1935-071","sc":1,"by":{"0":"35"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Trust","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"R.R. Ret. Bd. v. Alton R.R. Co.","cite":"295 U.S. 330","y":1935,"id":"scdb/1934-051","sc":1,"sum":"1. The power of Congress to regulate interstate commerce is subject to the guaranty of due process in the Fifth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7","1":"4, 35"}},{"t":"case","label":"Railway Exp. Agency, Inc. v. Virginia","cite":"347 U.S. 359","y":1954,"id":"scdb/1953-059","sc":1,"sum":"The gross-receipts tax is in fact and effect a privilege tax, and its application to a foreign corporation doing an exclusively interstate business violates the Commerce Clause of the Federal Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","2":"5"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"49"}},{"t":"case","label":"Sandifer v. U.S. Steel Corp.","cite":"134 S. Ct. 870","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/870/","sc":1,"by":{"0":"21, 29, 34, 41"}},{"t":"case","label":"Standard Office Bldg. Corp. v. United States","cite":"819 F.2d 1371","y":1987,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/1371/","by":{"0":"45"}},{"t":"case","label":"Union Pacific R.R. Co. v. United States","cite":"865 F.3d 1045","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/865/1045/","by":{"0":"4, 18, 20, 23, 28","2":"4, 11, 14, 17"}},{"t":"case","label":"34, 35, 36, 37, 38 United States v. Atl. Research Corp.","cite":"551 U.S. 128","y":2007,"id":"2006/06-562","sc":1,"sum":"The Court ruled unanimously that Section 107(a) of CERCLA allows potentially responsible parties (PRPs) to sue other PRPs for cost recovery. The opinion by Justice Clarence Thomas affirmed the Eighth Circuit and ruled for Atlantic Research.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"United States v. Phila. Nat’l Bank.","cite":"374 U.S. 321","y":1963,"id":"1962/83","sc":1,"sum":"The proposed consolidation of appellee banks is forbidden by § 7 of the Clayton Act, and it must be enjoined.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"United States v. Quality Stores","cite":"134 S. Ct. 1395","y":2014,"id":"2013/12-1408","sc":1,"sum":"The Court found that severance payments made to employees who were unwillingly laid off are taxable under the Federal Insurance Contributions Act.","sumSrc":"Oyez","by":{"0":"36","1":"26, 27, 30, 33","2":"13"}},{"t":"case","label":"United States v. Ressam","cite":"553 U.S. 272","y":2008,"id":"2007/07-455","sc":1,"sum":"The Court determined 8-1 that because Ressam was in possession of the explosives at the time he made the false statement to the customs agent he was therefore carrying them during the commission of that felony. Justice John Paul Stevens, in his majority opinion, refused to over-analyze the language of the statute and applied the word \"during\" in its most obvious sense.","sumSrc":"Oyez","by":{"0":"43","1":"49"}},{"t":"case","label":"United States v. Smith","cite":"756 F.3d 1179","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/756/1179/","by":{"0":"43"}},{"t":"case","label":"Util. Air Reg. Grp. v. EPA","cite":"134 S. Ct. 2427","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2427/","sc":1,"by":{"0":"49"}},{"t":"usc","label":"26 U.S.C. § 61","url":"https://www.law.cornell.edu/uscode/text/26/61","subs":["(a)"],"stext":{"head":"§61. Gross income defined","paras":[[0,"(a) General definition"],[0,"Except as otherwise provided in this subtitle, gross income means all income from whatever source derived, including (but not limited to) the following items:"],[1,"(1) Compensation for services, including fees, commissions, fringe benefits, and similar items;"],[1,"(2) Gross income derived from business;"],[1,"(3) Gains derived from dealings in property;"],[1,"(4) Interest;"],[1,"(5) Rents;"],[1,"(6) Royalties;"],[1,"(7) Dividends;"],[1,"(8) Annuities;"],[1,"(9) Income from life insurance and endowment contracts;"],[1,"(10) Pensions;"],[1,"(11) Income from discharge of indebtedness;"],[1,"(12) Distributive share of partnership gross income;"],[1,"(13) Income in respect of a decedent; and"],[1,"(14) Income from an interest in an estate or trust."],[0,"(b) Cross references"],[2,"For items specifically included in gross income, see part II (sec. 71 and following). For items specifically excluded from gross income, see part III (sec. 101 and following)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/61?type=usc&year=mostrecent&link-type=html"},"head":"§61. Gross income defined","tname":"Internal Revenue Code","by":{"0":"14","2":"12"}},{"t":"usc","label":"26 U.S.C. § 118","url":"https://www.law.cornell.edu/uscode/text/26/118","subs":["(c)"],"by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 119","url":"https://www.law.cornell.edu/uscode/text/26/119","subs":["(b)"],"stext":{"head":"§119. Meals or lodging furnished for the convenience of the employer","paras":[[0,"(a) Meals and lodging furnished to employee, his spouse, and his dependents, pursuant to employment"],[0,"There shall be excluded from gross income of an employee the value of any meals or lodging furnished to him, his spouse, or any of his dependents by or on behalf of his employer for the convenience of the employer, but only if—"],[1,"(1) in the case of meals, the meals are furnished on the business premises of the employer, or"],[1,"(2) in the case of lodging, the employee is required to accept such lodging on the business premises of his employer as a condition of his employment."],[0,"(b) Special rules"],[0,"For purposes of subsection (a)—"],[0,"(1) Provisions of employment contract or State statute not to be determinative"],[1,"In determining whether meals or lodging are furnished for the convenience of the employer, the provisions of an employment contract or of a State statute fixing terms of employment shall not be determinative of whether the meals or lodging are intended as compensation."],[0,"(2) Certain factors not taken into account with respect to meals"],[1,"In determining whether meals are furnished for the convenience of the employer, the fact that a charge is made for such meals, and the fact that the employee may accept or decline such meals, shall not be taken into account."],[0,"(3) Certain fixed charges for meals"],[0,"(A) In general"],[2,"If—"],[3,"(i) an employee is required to pay on a periodic basis a fixed charge for his meals, and"],[3,"(ii) such meals are furnished by the employer for the convenience of the employer,"],[2,"there shall be excluded from the employee's gross income an amount equal to such fixed charge."],[0,"(B) Application of subparagraph (A)"],[2,"Subparagraph (A) shall apply—"],[3,"(i) whether the employee pays the fixed charge out of his stated compensation or out of his own funds, and"],[3,"(ii) only if the employee is required to make the payment whether he accepts or declines the meals."],[0,"(4) Meals furnished to employees on business premises where meals of most employees are otherwise excludable"],[1,"All meals furnished on the business premises of an employer to such employer's employees shall be treated as furnished for the convenience of the employer if, without regard to this paragraph, more than half of the employees to whom such meals are furnished on such premises are furnished such meals for the convenience of the employer."],[0,"(c) Employees living in certain camps"],[0,"(1) In general"],[1,"In the case of an individual who is furnished lodging in a camp located in a foreign country by or on behalf of his employer, such camp shall be considered to be part of the business premises of the employer."],[0,"(2) Camp"],[1,"For purposes of this section, a camp constitutes lodging which is—"],[2,"(A) provided by or on behalf of the employer for the convenience of the employer because the place at which such individual renders services is in a remote area where satisfactory housing is not available on the open market,"],[2,"(B) located, as near as practicable, in the vicinity of the place at which such individual renders services, and"],[2,"(C) furnished in a common area (or enclave) which is not available to the public and which normally accommodates 10 or more employees."],[0,"(d) Lodging furnished by certain educational institutions to employees"],[0,"(1) In general"],[1,"In the case of an employee of an educational institution, gross income shall not include the value of qualified campus lodging furnished to such employee during the taxable year."],[0,"(2) Exception in cases of inadequate rent"],[1,"Paragraph (1) shall not apply to the extent of the excess of—"],[2,"(A) the lesser of—"],[3,"(i) 5 percent of the appraised value of the qualified campus lodging, or"],[3,"(ii) the average of the rentals paid by individuals (other than employees or students of the educational institution) during such calendar year for lodging provided by the educational institution which is comparable to the qualified campus lodging provided to the employee, over"],[2,"(B) the rent paid by the employee for the qualified campus lodging during such calendar year."],[1,"The appraised value under subparagraph (A)(i) shall be determined as of the close of the calendar year in which the taxable year begins, or, in the case of a rental period not greater than 1 year, at any time during the calendar year in which such period begins."],[0,"(3) Qualified campus lodging"],[1,"For purposes of this subsection, the term \"qualified campus lodging\" means lodging to which subsection (a) does not apply and which is—"],[2,"(A) located on, or in the proximity of, a campus of the educational institution, and"],[2,"(B) furnished to the employee, his spouse, and any of his dependents by or on behalf of such institution for use as a residence."],[0,"(4) Educational institution, etc."],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"educational institution\" means—"],[3,"(i) an institution described in section 170(b)(1)(A)(ii) (or an entity organized under State law and composed of public institutions so described), or"],[3,"(ii) an academic health center."],[0,"(B) Academic health center"],[2,"For purposes of subparagraph (A), the term \"academic health center\" means an entity—"],[3,"(i) which is described in section 170(b)(1)(A)(iii),"],[3,"(ii) which receives (during the calendar year in which the taxable year of the taxpayer begins) payments under subsection (d)(5)(B) or (h) of section 1886 of the Social Security Act (relating to graduate medical education), and"],[3,"(iii) which has as one of its principal purposes or functions the providing and teaching of basic and clinical medical science and research with the entity's own faculty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/119?type=usc&year=mostrecent&link-type=html"},"head":"§119. Meals or lodging furnished for the convenience of the employer","tname":"Internal Revenue Code","by":{"0":"38, 39","2":"17"}},{"t":"usc","label":"26 U.S.C. § 170","url":"https://www.law.cornell.edu/uscode/text/26/170","subs":["(g)"],"by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 306","url":"https://www.law.cornell.edu/uscode/text/26/306","subs":["(c)"],"by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 317","url":"https://www.law.cornell.edu/uscode/text/26/317","subs":["(a)"],"by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 461","url":"https://www.law.cornell.edu/uscode/text/26/461","subs":["(f)"],"by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 465","url":"https://www.law.cornell.edu/uscode/text/26/465","subs":["(c)"],"by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/26/1001","subs":["(b)"],"by":{"0":"33"}},{"t":"usc","label":"26 U.S.C. § 3121","url":"https://www.law.cornell.edu/uscode/text/26/3121","subs":["(a)","(b)","(a)(7)","(a)(8)","(a)(19)","(a)(20)","(b)(9)"],"stext":{"head":"§3121. Definitions","paras":[[0,"(a) Wages"],[0,"For purposes of this chapter, the term \"wages\" means all remuneration for employment, including the cash value of all remuneration (including benefits) paid in any medium other than cash; except that such term shall not include—"],[1,"(1) in the case of the taxes imposed by sections 3101(a) and 3111(a) that part of the remuneration which, after remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) equal to the contribution and benefit base (as determined under section 230 of the Social Security Act) with respect to employment has been paid to an individual by an employer during the calendar year with respect to which such contribution and benefit base is effective, is paid to such individual by such employer during such calendar year. If an employer (hereinafter referred to as successor employer) during any calendar year acquires substantially all the property used in a trade or business of another employer (hereinafter referred to as a predecessor), or used in a separate unit of a trade or business of a predecessor, and immediately after the acquisition employs in his trade or business an individual who immediately prior to the acquisition was employed in the trade or business of such predecessor, then, for the purpose of determining whether the successor employer has paid remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) with respect to employment equal to the contribution and benefit base (as determined under section 230 of the Social Security Act) to such individual during such calendar year, any remuneration (other than remuneration referred to in the succeeding paragraphs of this subsection) with respect to employment paid (or considered under this paragraph as having been paid) to such individual by such predecessor during such calendar year and prior to such acquisition shall be considered as having been paid by such successor employer;"],[1,"(2) the amount of any payment (including any amount paid by an employer for insurance or annuities, or into a fund, to provide for any such payment) made to, or on behalf of, an employee or any of his dependents under a plan or system established by an employer which makes provision for his employees generally (or for his employees generally and their dependents) or for a class or classes of his employees (or for a class or classes of his employees and their dependents), on account of—"],[2,"(A) sickness or accident disability (but, in the case of payments made to an employee or any of his dependents, this subparagraph shall exclude from the term \"wages\" only payments which are received under a workman's compensation law), or"],[2,"(B) medical or hospitalization expenses in connection with sickness or accident disability, or"],[2,"(C) death, except that this paragraph does not apply to a payment for group-term life insurance to the extent that such payment is includible in the gross income of the employee;"],[1,"[(3) Repealed. Pub. L. 98–21, title III, §324(a)(3)(B), Apr. 20, 1983, 97 Stat. 123]"],[1,"(4) any payment on account of sickness or accident disability, or medical or hospitalization expenses in connection with sickness or accident disability, made by an employer to, or on behalf of, an employee after the expiration of 6 calendar months following the last calendar month in which the employee worked for such employer;"],[1,"(5) any payment made to, or on behalf of, an employee or his beneficiary—"],[2,"(A) from or to a trust described in section 401(a) which is exempt from tax under section 501(a) at the time of such payment unless such payment is made to an employee of the trust as remuneration for services rendered as such employee and not as a beneficiary of the trust,"],[2,"(B) under or to an annuity plan which, at the time of such payment, is a plan described in section 403(a),"],[2,"(C) under a simplified employee pension (as defined in section 408(k)(1)), other than any contributions described in section 408(k)(6),"],[2,"(D) under or to an annuity contract described in section 403(b), other than a payment for the purchase of such contract which is made by reason of a salary reduction agreement (whether evidenced by a written instrument or otherwise),"],[2,"(E) under or to an exempt governmental deferred compensation plan (as defined in subsection (v)(3)),"],[2,"(F) to supplement pension benefits under a plan or trust described in any of the foregoing provisions of this paragraph to take into account some portion or all of the increase in the cost of living (as determined by the Secretary of Labor) since retirement but only if such supplemental payments are under a plan which is treated as a welfare plan under section 3(2)(B)(ii) of the Employee Retirement Income Security Act of 1974,"],[2,"(G) under a cafeteria plan (within the meaning of section 125) if such payment would not be treated as wages without regard to such plan and it is reasonable to believe that (if section 125 applied for purposes of this section) section 125 would not treat any wages as constructively received,"],[2,"(H) under an arrangement to which section 408(p) applies, other than any elective contributions under paragraph (2)(A)(i) thereof, or"],[2,"(I) under a plan described in section 457(e)(11)(A)(ii) and maintained by an eligible employer (as defined in section 457(e)(1));"],[1,"(6) the payment by an employer (without deduction from the remuneration of the employee)—"],[2,"(A) of the tax imposed upon an employee under section 3101, or"],[2,"(B) of any payment required from an employee under a State unemployment compensation law,"],[1,"with respect to remuneration paid to an employee for domestic service in a private home of the employer or for agricultural labor;"],[1,"(7)(A) remuneration paid in any medium other than cash to an employee for service not in the course of the employer's trade or business or for domestic service in a private home of the employer;"],[1,"(B) cash remuneration paid by an employer in any calendar year to an employee for domestic service in a private home of the employer (including domestic service on a farm operated for profit), if the cash remuneration paid in such year by the employer to the employee for such service is less than the applicable dollar threshold (as defined in subsection (x)) for such year;"],[1,"(C) cash remuneration paid by an employer in any calendar year to an employee for service not in the course of the employer's trade or business, if the cash remuneration paid in such year by the employer to the employee for such service is less than $100. As used in this subparagraph, the term \"service not in the course of the employer's trade or business\" does not include domestic service in a private home of the employer and does not include service described in subsection (g)(5);"],[1,"(8)(A) remuneration paid in any medium other than cash for agricultural labor;"],[1,"(B) cash remuneration paid by an employer in any calendar year to an employee for agricultural labor unless—"],[2,"(i) the cash remuneration paid in such year by the employer to the employee for such labor is $150 or more, or"],[2,"(ii) the employer's expenditures for agricultural labor in such year equal or exceed $2,500,"],[1,"except that clause (ii) shall not apply in determining whether remuneration paid to an employee constitutes \"wages\" under this section if such employee (I) is employed as a hand harvest laborer and is paid on a piece rate basis in an operation which has been, and is customarily and generally recognized as having been, paid on a piece rate basis in the region of employment, (II) commutes daily from his permanent residence to the farm on which he is so employed, and (III) has been employed in agriculture less than 13 weeks during the preceding calendar year;"],[1,"[(9) Repealed. Pub. L. 98–21, title III, §324(a)(3)(B), Apr. 20, 1983, 97 Stat. 123]"],[1,"(10) remuneration paid by an employer in any calendar year to an employee for service described in subsection (d)(3)(C) (relating to home workers), if the cash remuneration paid in such year by the employer to the employee for such service is less than $100;"],[1,"(11) remuneration paid to or on behalf of an employee if (and to the extent that) at the time of the payment of such remuneration it is reasonable to believe that a corresponding deduction is allowable under section 217 (determined without regard to section 274(n));"],[1,"(12)(A) tips paid in any medium other than cash;"],[1,"(B) cash tips received by an employee in any calendar month in the course of his employment by an employer unless the amount of such cash tips is $20 or more;"],[1,"(13) any payment or series of payments by an employer to an employee or any of his dependents which is paid—"],[2,"(A) upon or after the termination of an employee's employment relationship because of (i) death, or (ii) retirement for disability, and"],[2,"(B) under a plan established by the employer which makes provision for his employees generally or a class or classes of his employees (or for such employees or class or classes of employees and their dependents),"],[1,"other than any such payment or series of payments which would have been paid if the employee's employment relationship had not been so terminated;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3121?type=usc&year=mostrecent&link-type=html"},"head":"§3121. Definitions","tname":"Internal Revenue Code","by":{"0":"3, 9, 18, 37, 39, 41, 44, 7, 19, 45, 49","1":"6, 6, 6, 6, 6, 6","2":"1, 18, 21, 23"}},{"t":"usc","label":"26 U.S.C. § 3201","url":"https://www.law.cornell.edu/uscode/text/26/3201","subs":["(a)","(b)"],"stext":{"head":"§3201. Rate of tax","paras":[[0,"(a) Tier 1 tax"],[0,"In addition to other taxes, there is hereby imposed on the income of each employee a tax equal to the applicable percentage of the compensation received during any calendar year by such employee for services rendered by such employee. For purposes of the preceding sentence, the term \"applicable percentage\" means the percentage equal to the sum of the rates of tax in effect under subsections (a) and (b) of section 3101 for the calendar year."],[0,"(b) Tier 2 tax"],[0,"In addition to other taxes, there is hereby imposed on the income of each employee a tax equal to the percentage determined under section 3241 for any calendar year of the compensation received during such calendar year by such employee for services rendered by such employee."],[0,"(c) Cross reference"],[2,"For application of different contribution bases with respect to the taxes imposed by subsections (a) and (b), see section 3231(e)(2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3201?type=usc&year=mostrecent&link-type=html"},"head":"§3201. Rate of tax","tname":"Internal Revenue Code","by":{"0":"9, 20","1":"2, 2, 45, 2"}},{"t":"usc","label":"26 U.S.C. § 3221","url":"https://www.law.cornell.edu/uscode/text/26/3221","subs":["(a)","(b)"],"stext":{"head":"§3221. Rate of tax","paras":[[0,"(a) Tier 1 tax"],[0,"In addition to other taxes, there is hereby imposed on every employer an excise tax, with respect to having individuals in his employ, equal to the applicable percentage of compensation paid during any calendar year by such employer for services rendered to such employer. For purposes of the preceding sentence, the term \"applicable percentage\" means the percentage equal to the sum of the rates of tax in effect under subsections (a) and (b) of section 3111 for the calendar year."],[0,"(b) Tier 2 tax"],[0,"In addition to other taxes, there is hereby imposed on every employer an excise tax, with respect to having individuals in his employ, equal to the percentage determined under section 3241 for any calendar year of the compensation paid during such calendar year by such employer for services rendered to such employer."],[0,"(c) Cross reference"],[2,"For application of different contribution bases with respect to the taxes imposed by subsections (a) and (b), see section 3231(e)(2)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3221?type=usc&year=mostrecent&link-type=html"},"head":"§3221. Rate of tax","tname":"Internal Revenue Code","by":{"0":"9, 20","1":"2, 2"}},{"t":"usc","label":"26 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/26/3231","subs":["(a)","(e)","(e)(1)","(e)(1)(i)","(e)(5)","(e)(9)","(e)(12)","(e)(12)(A)"],"stext":{"head":"§3231. Definitions","paras":[[0,"(a) Employer"],[0,"For purposes of this chapter, the term \"employer\" means any carrier (as defined in subsection (g)), and any company which is directly or indirectly owned or controlled by one or more such carriers or under common control therewith, and which operates any equipment or facility or performs any service (except trucking service, casual service, and the casual operation of equipment or facilities) in connection with the transportation of passengers or property by railroad, or the receipt, delivery, elevation, transfer in transit, refrigeration or icing, storage, or handling of property transported by railroad, and any receiver, trustee, or other individual or body, judicial or otherwise, when in the possession of the property or operating all or any part of the business of any such employer; except that the term \"employer\" shall not include any street, interurban, or suburban electric railway, unless such railway is operating as a part of a general steam-railroad system of transportation, but shall not exclude any part of the general steam-railroad system of transportation now or hereafter operated by any other motive power. The Surface Transportation Board is hereby authorized and directed upon request of the Secretary, or upon complaint of any party interested, to determine after hearing whether any line operated by electric power falls within the terms of this exception. The term \"employer\" shall also include railroad associations, traffic associations, tariff bureaus, demurrage bureaus, weighing and inspection bureaus, collection agencies and other associations, bureaus, agencies, or organizations controlled and maintained wholly or principally by two or more employers as hereinbefore defined and engaged in the performance of services in connection with or incidental to railroad transportation; and railway labor organizations, national in scope, which have been or may be organized in accordance with the provisions of the Railway Labor Act, as amended (45 U.S.C., chapter 8), and their State and National legislative committees and their general committees and their insurance departments and their local lodges and divisions, established pursuant to the constitutions and bylaws of such organizations. The term \"employer\" shall not include any company by reason of its being engaged in the mining of coal, the supplying of coal to an employer where delivery is not beyond the mine tipple, and the operation of equipment or facilities therefor, or in any of such activities."],[0,"(b) Employee"],[0,"For purposes of this chapter, the term \"employee\" means any individual in the service of one or more employers for compensation. The term \"employee\" includes an officer of an employer. The term \"employee\" shall not include any individual while such individual is engaged in the physical operations consisting of the mining of coal, the preparation of coal, the handling (other than movement by rail with standard railroad locomotives) of coal not beyond the mine tipple, or the loading of coal at the tipple."],[0,"(c) Employee representative"],[0,"For purposes of this chapter, the term \"employee representative\" means any officer or official representative of a railway labor organization other than a labor organization included in the term \"employer\" as defined in subsection (a), who before or after June 29, 1937, was in the service of an employer as defined in subsection (a) and who is duly authorized and designated to represent employees in accordance with the Railway Labor Act (45 U.S.C., chapter 8), as amended, and any individual who is regularly assigned to or regularly employed by such officer or official representative in connection with the duties of his office."],[0,"(d) Service"],[0,"For purposes of this chapter, an individual is in the service of an employer whether his service is rendered within or without the United States, if—"],[1,"(1) he is subject to the continuing authority of the employer to supervise and direct the manner of rendition of his service, or he is rendering professional or technical services and is integrated into the staff of the employer, or he is rendering, on the property used in the employer's operations, other personal services the rendition of which is integrated into the employer's operations, and"],[1,"(2) he renders such service for compensation;"],[0,"except that an individual shall be deemed to be in the service of an employer, other than a local lodge or division or a general committee of a railway-labor-organization employer, not conducting the principal part of its business in the United States, only when he is rendering service to it in the United States; and an individual shall be deemed to be in the service of such a local lodge or division only if—"],[1,"(3) all, or substantially all, the individuals constituting its membership are employees of an employer conducting the principal part of its business in the United States; or"],[1,"(4) the headquarters of such local lodge or division is located in the United States;"],[0,"and an individual shall be deemed to be in the service of such a general committee only if—"],[1,"(5) he is representing a local lodge or division described in paragraph (3) or (4) immediately above; or"],[1,"(6) all, or substantially all, the individuals represented by it are employees of an employer conducting the principal part of its business in the United States; or"],[1,"(7) he acts in the capacity of a general chairman or an assistant general chairman of a general committee which represents individuals rendering service in the United States to an employer, but in such case if his office or headquarters is not located in the United States and the individuals represented by such general committee are employees of an employer not conducting the principal part of its business in the United States, only such proportion of the remuneration for such service shall be regarded as compensation as the proportion which the mileage in the United States under the jurisdiction of such general committee bears to the total mileage under its jurisdiction, unless such mileage formula is inapplicable, in which case such other formula as the Railroad Retirement Board may have prescribed pursuant to section 1(c) of the Railroad Retirement Act of 1937 (45 U.S.C. 228a) shall be applicable, and if the application of such mileage formula, or such other formula as the Board may prescribe, would result in the compensation of the individual being less than 10 percent of his remuneration for such service, no part of such remuneration shall be regarded as compensation;"],[0,"Provided however, That an individual not a citizen or resident of the United States shall not be deemed to be in the service of an employer when rendering service outside the United States to an employer who is required under the laws applicable in the place where the service is rendered to employ therein, in whole or in part, citizens or residents thereof; and the laws applicable on August 29, 1935, in the place where the service is rendered shall be deemed to have been applicable there at all times prior to that date."],[0,"(e) Compensation"],[0,"For purposes of this chapter—"],[1,"(1) The term \"compensation\" means any form of money remuneration paid to an individual for services rendered as an employee to one or more employers. Such term does not include (i) the amount of any payment (including any amount paid by an employer for insurance or annuities, or into a fund, to provide for any such payment) made to, or on behalf of, an employee or any of his dependents under a plan or system established by an employer which makes provision for his employees generally (or for his employees generally and their dependents) or for a class or classes of his employees (or for a class or classes of his employees and their dependents), on account of sickness or accident disability or medical or hospitalization expenses in connection with sickness or accident disability or death, except that this clause does not apply to a payment for group-term life insurance to the extent that such payment is includible in the gross income of the employee, (ii) tips (except as is provided under paragraph (3)), (iii) an amount paid specifically—either as an advance, as reimbursement or allowance—for traveling or other bona fide and necessary expenses incurred or reasonably expected to be incurred in the business of the employer provided any such payment is identified by the employer either by a separate payment or by specifically indicating the separate amounts where both wages and expense reimbursement or allowance are combined in a single payment, or (iv) any remuneration which would not (if chapter 21 applied to such remuneration) be treated as wages (as defined in section 3121(a)) by reason of section 3121(a)(5). Such term does not include remuneration for service which is performed by a nonresident alien individual for the period he is temporarily present in the United States as a nonimmigrant under subparagraph (F), (J), (M), or (Q) of section 101(a)(15) of the Immigration and Nationality Act, as amended, and which is performed to carry out the purpose specified in subparagraph (F), (J), (M), or (Q), as the case may be. For the purpose of determining the amount of taxes under sections 3201 and 3221, compensation earned in the service of a local lodge or division of a railway-labor-organization employer shall be disregarded with respect to any calendar month if the amount thereof is less than $25. Compensation for service as a delegate to a national or international convention of a railway labor organization defined as an \"employer\" in subsection (a) of this section shall be disregarded for purposes of determining the amount of taxes due pursuant to this chapter if the individual rendering such service has not previously rendered service, other than as such a delegate, which may be included in his \"years of service\" for purposes of the Railroad Retirement Act. Nothing in the regulations prescribed for purposes of chapter 24 (relating to wage withholding) which provides an exclusion from \"wages\" as used in such chapter shall be construed to require a similar exclusion from \"compensation\" in regulations prescribed for purposes of this chapter."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/3231?type=usc&year=mostrecent&link-type=html"},"head":"§3231. Definitions","tname":"Internal Revenue Code","by":{"0":"45, 1, 2, 8, 9, 10, 13, 18, 20, 23, 33, 36, 38, 39, 40, 43","1":"25, 25, 25, 25, 25, 25, 25","2":"1, 2, 12, 14, 15, 16, 17, 22"}},{"t":"usc","label":"45 U.S.C. § 51","url":"https://www.law.cornell.edu/uscode/text/45/51","by":{"0":"7"}},{"t":"usc","label":"45 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/45/151","by":{"0":"7"}},{"t":"usc","label":"45 U.S.C. § 231-231v","url":"https://www.law.cornell.edu/uscode/text/45/231-231v","by":{"0":"10"}},{"t":"usc","label":"45 U.S.C. § 231b","url":"https://www.law.cornell.edu/uscode/text/45/231b","subs":["(a)","(b)","(a)(1)"],"stext":{"head":"§231b. Computation of annuities","paras":[[0,"(a) Amount"],[0,"(1) The annuity of an individual under section 231a(a)(1) of this title shall be in an amount equal to the amount (before any reduction on account of age and before any deductions on account of work) of the old-age insurance benefit or disability insurance benefit to which such individual would have been entitled under the Social Security Act [42 U.S.C. 301 et seq.] if all of his or her service as an employee after December 31, 1936, had been included in the term \"employment\" as defined in that Act."],[0,"(2) For purposes of this subsection, individuals entitled to an annuity under section 231a(a)(1)(ii) of this title shall, except for the purposes of recomputations in accordance with section 215(f) of the Social Security Act [42 U.S.C. 415(f)], be deemed to have attained retirement age (as defined by section 216(l) of the Social Security Act [42 U.S.C. 416(l)]). For purposes of this subsection, individuals entitled to an annuity under paragraph (iv) or (v) of section 231a(a)(1) of this title shall be deemed to be entitled to a disability insurance benefit under section 223 of the Social Security Act [42 U.S.C. 423]."],[0,"(3) If an individual entitled to an annuity under section 231a(a)(1)(i) or (iii) of this title on the basis of less than ten years of service is entitled to a benefit under section 202(a), section 202(b), or section 202(c) of the Social Security Act [42 U.S.C. 402(a), (b), (c)] which began to accrue before the annuity under section 231a(a)(1)(i) or (iii) of this title, the annuity amount provided such individual under this subsection, shall be computed as though the annuity under this subchapter began to accrue on the later of (A) the date on which the benefit under section 202(a), section 202(b), or section 202(c) of the Social Security Act began, or (B) the date on which the individual first met the conditions for entitlement to an age reduced annuity under this subchapter other than the conditions set forth in sections 231a(e)(1) and 231a(e)(2) of this title and the requirement that an application be filed."],[0,"(b) Increased annuities under subsection (a)"],[0,"(1) The amount of the annuity of an individual provided under subsection (a) shall be increased by an amount equal to seven-tenths of 1 per centum of the product which is obtained by multiplying such individual's \"years of service\" by such individual's \"average monthly compensation\" as determined under this subsection. The annuity amount payable to the individual under this subsection shall be reduced by 25 per centum of the annuity amount computed for such individual under subsection (h)(1) or (h)(2), and subsection (h)(5), of this section without regard to section 231f(c)(1) of this title. An individual's \"average monthly compensation\" for purposes of this subsection shall be the quotient obtained by dividing by 60 such individual's total compensation for the 60 months, consecutive or otherwise, during which such individual received that individual's highest monthly compensation, except that no part of any month's compensation in excess of the maximum amount creditable for any individual for such month under subsection (j) of this section shall be recognized. In determining the months of compensation to be used for purposes of this subsection, the total compensation reported for the individual under section 231h of this title or credited to such individual under subsection (j) of this section for a year divided by the number of months of service credited to such individual under subsection (i) of this section with respect to such year shall be considered the monthly compensation of the individual for each month of service in any year for which records of the Board do not show the amount of compensation paid to the individual on a monthly basis. If the \"average monthly compensation\" computed under this subsection is not a multiple of $1, it shall be rounded to the next lower multiple of $1."],[0,"(2) For purposes of subdivision (1) of this subsection, in determining \"average monthly compensation\" for an individual who has not engaged in employment for an employer in the 60-month period preceding the month in which such individual's annuity began to accrue, and whose major employment during such 60-month period was for a United States department or agency named in section 231(o) of this title, the amount of compensation used with respect to each month used in making such determination shall be the product of—"],[1,"(i) the compensation credited to such individual for such month under paragraph (1) of this subsection; and"],[1,"(ii) the quotient obtained by dividing—"],[2,"(I) the average of total wages (as determined under section 215(b)(3)(A)(ii)(I) of the Social Security Act [42 U.S.C. 415(b)(3)(A)(ii)(I)]) for the second calendar year preceding the earliest of the year of the individual's death or the year in which an annuity begins to accrue to such individual (disregarding an annuity based on disability which is terminated because such individual has recovered from such disability if such individual engages in any regular employment after such termination); by"],[2,"(II) the average of total wages (as determined under section 215(b)(3)(A)(ii)(II) of the Social Security Act [42 U.S.C. 415(b)(3)(A)(ii)(II)]) for the calendar year during which such month occurred, unless such month occurred prior to calendar year 1951, in which case, the average of total wages so determined for 1951."],[0,"In no event shall \"average monthly compensation\" determined for an individual under this subdivision exceed the maximum \"average monthly compensation\" which can be determined under subdivision (1) of this subsection for any person retiring January 1 of the year in which such individual's annuity began to accrue."],[0,"(c), (d) Repealed. Pub. L. 97–35, title XI, §1118(b), Aug. 13, 1981, 95 Stat. 631"],[0,"(e) Supplemental annuities"],[0,"The supplemental annuity of an individual under section 231a(b) of this title shall be $23 plus an additional amount of $4 for each year of service that the individual has in excess of 25 years, but in no case shall the supplemental annuity exceed $43."],[0,"(f) Reductions in annuities"],[0,"(1) If, in the case of an individual whose annuity under section 231a(a)(1) of this title began to accrue prior to January 1, 1983, the annuity (before any reduction due to such individual's entitlement to a monthly insurance benefit under the Social Security Act [42 U.S.C. 301 et seq.] and disregarding any amount provided by subsection (h) of this section) plus the supplemental annuity to which such individual is entitled for any month under this subchapter, together with the annuity, if any, of the spouse of such individual (before any reduction due to such spouse's entitlement to a wife's or husband's insurance benefit under the Social Security Act and disregarding any amount provided by section 231c(e) of this title), before any reductions under the provisions of section 231a(f) of this title is less than the total amount which would have been payable to such individual and his spouse for such month, on the basis of the individual's compensation and years of service, under the provisions of the Railroad Retirement Act of 1937 as in effect on December 31, 1974 [45 U.S.C. 228a et seq.], disregarding, for purposes of the computations under such Railroad Retirement Act of 1937 compensation for any month after December 31, 1974, in excess of one-twelfth of the maximum annual taxable \"wages\" (as defined in section 3121 of the Internal Revenue Code of 1986 [26 U.S.C. 3121]) for the calendar year 1974, the annuity of such individual and the annuity of such spouse, if any, shall be increased proportionately so as to equal such total amount. For the purpose of computing amounts under this subdivision, the Board shall have the authority to approximate the effect of the reductions prescribed by sections 3(a)(2) and 3(a)(3) of the Railroad Retirement Act of 1937 [45 U.S.C. 228c(a)(2), (a)(3)]. For purposes of computing amounts payable under the Railroad Retirement Act of 1937, any increases in the amounts determined under the first proviso of section 3(e) of such Act which would have become effective after December 31, 1974, shall be disregarded."],[0,"(2) If for any month in which an annuity accrues and is payable under this subchapter the annuity to which an individual is entitled under this subchapter (or would have been entitled except for a reduction pursuant to a joint and survivor election), together with the annuity, if any, of the spouse and divorced wife of such individual, is less than the total amount, or the additional amount, which would have been payable to all persons for such month under the Social Security Act [42 U.S.C. 301 et seq.] if such individual's service as an employee after December 31, 1936, were included in the term \"employment\" as defined in that Act, the annuities of the individual and spouse shall be increased proportionately to such total amount, or such additional amount: Provided, however, That if an annuity accrues to an individual or a spouse for a part of a month, the amount payable for such part of a month under this subdivision shall be one-thirtieth of the amount payable under this subdivision for an entire month, multiplied by the number of days in such part of a month. For purposes of this subdivision, (i) persons not entitled to an annuity under section 231a of this title shall not be included in the computation under this subdivision except a spouse who could qualify for an annuity under section 231a(c) of this title if the individual from whom the spouse's annuity under this subchapter would derive had attained age 60 or 62, as the case may be, and such individual's children who meet the definition as such contained in section 216(e) of the Social Security Act [42 U.S.C. 416(e)]; (ii) after an annuity has been certified for payment and this subdivision was inapplicable after allowing for any waiting period under section 223(c)(2) of the Social Security Act [42 U.S.C. 423(c)(2)], and after having considered the inclusion of all persons who were then eligible for inclusion in the computation under this subdivision, or was then applicable but later became inapplicable, any recertification in such annuity under this subdivision shall not take into account persons not entitled to an annuity under section 231a of this title except a spouse who could qualify for an annuity under section 231a(c) of this title when she attains age 60 or 62, as the case may be, if the individual from whom the spouse's annuity would derive had attained age 60 or 62, as the case may be, and who was married to such individual at the time he applied for his annuity; and (iii) in computing the amount to be paid under this subdivision the only benefits under title II of the Social Security Act [42 U.S.C. 401 et seq.] which shall be considered shall be those to which the persons included in the computation are entitled."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/45/231b?type=usc&year=mostrecent&link-type=html"},"head":"§231b. Computation of annuities","tname":"Railroads","by":{"0":"9, 10","1":"2","2":"21"}},{"t":"usc","label":"49 U.S.C. § 20","url":"https://www.law.cornell.edu/uscode/text/49/20","subs":["(1)(1934)"],"by":{"0":"26"}},{"t":"reg","label":"26 C.F.R. § 1.422-5","url":"https://www.ecfr.gov/current/title-26/section-1.422-5","subs":["(c)"],"by":{"0":"37","2":"2, 14"}},{"t":"reg","label":"26 C.F.R. § 31.3231","url":"https://www.ecfr.gov/current/title-26/section-31.3231","subs":["(e)"],"by":{"0":"12, 19, 47, 49","2":"22"}},{"t":"reg","label":"26 C.F.R. § 301.6311-1","url":"https://www.ecfr.gov/current/title-26/section-301.6311-1","by":{"0":"33","2":"3"}},{"t":"reg","label":"26 C.F.R. § 301.6311-2","url":"https://www.ecfr.gov/current/title-26/section-301.6311-2","by":{"0":"33","2":"3"}},{"t":"reg","label":"26 C.F.R. § 410.5","url":"https://www.ecfr.gov/current/title-26/section-410.5","by":{"0":"11, 26, 27, 47","2":"2, 8"}},{"t":"reg","label":"26 C.F.R. § 410.6","url":"https://www.ecfr.gov/current/title-26/section-410.6","by":{"0":"11","2":"8, 9"}},{"t":"reg","label":"Internal Revenue Service, Update of Railroad Retirement Tax Act Regulations, 58 Fed. Reg. 28,366","url":"https://www.govinfo.gov/link/fr/58/28366","by":{"0":"11, 49"}},{"t":"case","label":"American Bank & Trust Co. v. Dallas County","cite":"463 U.S. 855","y":1983,"id":"1982/81-1717","sc":1,"sum":"1.The Texas tax on bank shares violates Rev. Stat. §3701, as amended.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 30"}},{"t":"case","label":"Arkansas Best Corp. v. Commissioner","cite":"485 U.S. 212","y":1988,"id":"1987/86-751","sc":1,"sum":"A taxpayer's motivation in purchasing an asset is irrelevant to the question whether it falls within the broad definition of \"capital asset\" in § 1221. Petitioner's reading of Corn Products as authorizing ordinaryasset treatment for any asset acquired and held for business rather than investment purposes is too expansive. That reading finds no support in § 1221's language, which does not mention a business-motive …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 33"}},{"t":"case","label":"Atlantic Land & Improvemnt Co. v. United States","cite":"790 F.2d 853","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/790/853/","by":{"1":"38"}},{"t":"case","label":"Baldwin v. Baldwin","cite":"151 A. 741","y":1930,"court":"N.J. Ch.","url":"https://www.courtlistener.com/c/A./151/741/","by":{"1":"23"}},{"t":"case","label":"Bond v. United States","cite":"134 S. Ct. 2077","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Bonham v. Commissioner","cite":"89 F.2d 725","y":1937,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/89/725/","by":{"1":"19"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 42"}},{"t":"case","label":"CSX Corp. v. United States","cite":"2017 WL 2800181","y":2017,"court":"M.D. Fla. May 2","by":{"1":"10, 20, 43"}},{"t":"case","label":"Chaplin v. Commissioner","cite":"136 F.2d 298","y":1943,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/136/298/","by":{"1":"19"}},{"t":"case","label":"Commissioner v. Smith","cite":"324 U.S. 177","y":1945,"id":"scdb/1944-153","sc":1,"sum":"An employer gave to its employee as compensation for his services an option to purchase shares of stock at a price not less than the then value of the stock. The option had no value at that time, and the compensation contemplated by the parties was the transfer to the employee of the shares of stock after their value had increased to more than the option price. Held, under § 22 (a) of the Revenue Act of 1938 and of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Cottage Sav. Ass’n v. Commissioner","cite":"499 U.S. 554","y":1991,"id":"1990/89-1965","sc":1,"sum":"In a 7-to-2 decision, the Supreme Court held that the definition of \"substantially identical\" under the FHLBB regulations was intentionally flexible and broad enough to include even properties that were \"materially different\" for IRS purposes.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Eisner v. Macomber","cite":"252 U.S. 189","y":1920,"id":"scdb/1919-124","sc":1,"sum":"Congress was not empowered by the Sixteenth Amendment to tax, as income of the stockholder, without apportionment, a stock dividend made lawfully and in' good faith against profits accumulated by the corporation since March 1,1913. P. 201. Toume v. Mmer, 245 U. S. 418.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Gandy v. Stanton","cite":"157 A. 894","y":1931,"court":"N.J. Ch.","url":"https://www.courtlistener.com/c/A./157/894/","by":{"1":"23"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"sum":"In a 5-to-4 decision written by Justice Ruth Bader Ginsburg, the Court held that the intention of the Tax Injunction Act (TIA) was to prevent taxpayers from trying to avoid their state taxes through federal litigation. TIA was not intended, however, to prevent all federal interference with state taxation.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Hinkley v. Primm","cite":"41 Ill. App. 579","y":1892,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/Ill.%20App./41/579/","by":{"1":"23"}},{"t":"case","label":"Industrial Trust Co. v. Saunders","cite":"42 A.2d 492","y":1945,"court":"R.I.","url":"https://www.courtlistener.com/c/A.2d/42/492/","ar":1,"by":{"1":"23"}},{"t":"case","label":"Jenkins v. Fowler","cite":"63 N.H. 244","y":1884,"url":"https://www.courtlistener.com/c/N.H./63/244/","by":{"1":"23"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"1":"58"}},{"t":"case","label":"Lane v. Railey","cite":"133 S.W.2d 74","y":1939,"url":"https://www.courtlistener.com/c/S.W.2d/133/74/","by":{"1":"23","2":"8"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Loughrin v. United States","cite":"134 S. Ct. 2384","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"McCullen v. Daughtrey","cite":"129 S.E. 611","y":1925,"court":"N.C.","url":"https://www.courtlistener.com/c/S.E./129/611/","by":{"1":"22"}},{"t":"case","label":"McGovern v. United States","cite":"272 F. 262","y":1921,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F./272/262/","by":{"1":"22"}},{"t":"case","label":"Mt. Holly Safe Deposit & Trust Co. v. Deacon","cite":"81 A. 356","y":1911,"court":"N.J. Ch.","url":"https://www.courtlistener.com/c/A./81/356/","by":{"1":"22"}},{"t":"case","label":"Mutual Life Ins. Co. v. Spohn","cite":"188 S.W. 1078","y":1916,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W./188/1078/","sum":"Stating that “ ‘money’ is often used in wills in a broad and elastic sense” to encompass “ground rents, bonds and notes,” among other interests.","sumSrc":"brief:1","by":{"1":"22"}},{"t":"case","label":"Norwegian Nitrogen Prods. Co. v. United States","cite":"288 U.S. 294","y":1933,"id":"scdb/1932-150","sc":1,"sum":"The Tariff Act of 1922 empowers the President to change rates of duty in order to equalize differences in costs of production in this country and abroad, but provides--§ 315 (c)-that before he acts there shall have been an investigation of such differences by the Tariff Commission, in the making of which the Commission shall give reasonable public notice of its hearings, and shall give \"reasonable opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Paul v. Bell","cite":"31 Tex. 10","y":1868,"url":"https://www.courtlistener.com/c/Tex./31/10/","by":{"1":"22"}},{"t":"case","label":"Pension Benefit Guar. Corp. v. The LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Perkins v. Mathes","cite":"49 N.H. 107","y":1869,"url":"https://www.courtlistener.com/c/N.H./49/107/","by":{"1":"23"}},{"t":"case","label":"Prescott v. Commissioner","cite":"76 F.2d 3","y":1935,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/76/3/","by":{"1":"19"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"1":"42, 50"}},{"t":"case","label":"Smith v. Burch","cite":"92 N.Y. 228","y":1882,"url":"https://www.courtlistener.com/c/N.Y./92/228/","by":{"1":"22"}},{"t":"case","label":"Star Athletica, LLC v. Varsity Brands, Inc.","cite":"137 S. Ct. 1002","y":2017,"id":"2016/15-866","sc":1,"sum":"The Court determined that the test for deciding whether a feature of a “useful article” is copyrightable under the Copyright Act is whether the feature can be perceived as a two- or three-dimensional artwork that is separable from the useful article and if it would be a protectable pictorial, graphical, or sculptural work on its own.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Texas Dep’t of Hous. & Community Affairs v. Inclusive Communities Project, Inc.","cite":"135 S. Ct. 2507","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Tyler v. Cain","cite":"533 U.S. 656","y":2001,"id":"2000/00-5961","sc":1,"sum":"The Court held that the Cage rule was not \"made retroactive to cases on collateral review by the Supreme Court.\" Justice Thomas wrote for the Court that \"[b]ecause 'made' means 'held'...it is clear that the Cage rule has not been 'made retroactive to cases on collateral review by the Supreme Court.' Cage itself does not hold that it is retroactive.","sumSrc":"Oyez","by":{"1":"50"}},{"t":"case","label":"Union Pac. R.R. v. United States","cite":"2016 U.S. Dist. LEXIS 86023","y":2016,"court":"D. Neb. July 1","sum":"Observing that Union Pacific issued stock options beginning in tax year 1981 and paid RRTA taxes on the options “without challenge” until filing a refund suit in 2014 concerning tax years 1991 to 2007.","sumSrc":"brief:1","by":{"1":"7"}},{"t":"case","label":"United States v. Clintwood Elkhorn Mining Co.","cite":"553 U.S. 1","y":2008,"id":"2007/07-308","sc":1,"sum":"Jr., the Court refused to pay Clintwood refunds for the unconstitutionally levied taxes. The Court stated that the remedy for taxes imposed in violation of the Export Clause is the same as for any other unlawful tax: filing a timely administrative refund claim.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"United States v. Estate of Romani","cite":"523 U.S. 517","y":1998,"id":"1997/96-1613","sc":1,"sum":"The Court held that section 3713(a) does not require that a federal tax claim be given preference over a judgment creditor's perfected lien on real property.","sumSrc":"Oyez","by":{"1":"28","2":"13"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"ar":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","2":"13"}},{"t":"case","label":"United States v. Silk","cite":"331 U.S. 704","y":1947,"id":"scdb/1946-119","sc":1,"ar":1,"sum":"1. In determining whether particular workers are independent contractors or \"employees\" within the meaning of the Social Security Act, the same rules are applicable as were applied by this Court to the National Labor Relations Act in Labor Board v. Hearst Publications,322 U. S. 111.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14, 43"}},{"t":"case","label":"Universal Carloading & Distrib. Co. v. Pedrick","cite":"184 F.2d 64","y":1950,"url":"https://www.courtlistener.com/c/F.2d/184/64/","by":{"1":"38"}},{"t":"case","label":"West Va. Univ. Hosps. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"ar":1,"sum":"Fees for services rendered by experts in civil rights litigation may not be shifted to the losing party as part of \"a reasonable attorney's fee\" under § 1988.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28","2":"13"}},{"t":"usc","label":"45 U.S.C. § 231","url":"https://www.law.cornell.edu/uscode/text/45/231","subs":["(h)(1)"],"by":{"1":"2, 38, 46"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(c)(5)(ii)"],"by":{"1":"25"}},{"t":"reg","label":"59 Fed. Reg. 66,188","url":"https://www.govinfo.gov/link/fr/59/66188","by":{"1":"15, 37, 45, 46, 47"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"2":"14, 16"}},{"t":"case","label":"Clark v. Rameker","cite":"134 S. Ct. 2242","y":2014,"id":"2013/13-299","sc":1,"sum":"The Court held that the U.S. Bankruptcy Code does not exempt inherited retirement accounts from a debtor's estate in bankruptcy proceedings.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Digital Realty Trust v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Keokee Consol. Coke Co. v. W.W. Taylor","cite":"234 U.S. 224","y":1914,"id":"scdb/1913-093","sc":1,"sum":"This court does not go behind the construction given to a state statute by the state courts.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Thompson v. Butler","cite":"95 U.S. 694","y":1877,"id":"scdb/1877-101","sc":1,"sum":"In a suit in the Circuit Court, where the defendant pleaded neither a set-off nor a counter-claim, the plaintiff remitted so much of a verdict in his favor as was in excess of $5,000, and took judgment for the remainder “in coin.” The defendant sued out a writ of error. Held, that the amount in controversy, whether payable in coin or any other kind of money, is not sufficient to give this court jurisdiction.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Warner v. Goltra","cite":"293 U.S. 155","y":1934,"id":"scdb/1934-043","sc":1,"sum":"1. In § 33 of the Merchant Marine Act of 1920, giving to \"any seaman\" injured in the course of his employment a cause of action for damages similar to that given by the statutes of the United States to railway employees, the term \" any seaman\" includes the master of the vessel.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16"}},{"t":"usc","label":"26 U.S.C. § 274","url":"https://www.law.cornell.edu/uscode/text/26/274","subs":["(j)"],"by":{"2":"17"}},{"t":"usc","label":"26 U.S.C. § 74","url":"https://www.law.cornell.edu/uscode/text/26/74","subs":["(c)"],"by":{"2":"12, 17"}},{"t":"usc","label":"26 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/26/101","by":{"2":"12"}},{"t":"usc","label":"26 U.S.C. § 108","url":"https://www.law.cornell.edu/uscode/text/26/108","subs":["(f)"],"by":{"2":"12"}},{"t":"usc","label":"26 U.S.C. § 117","url":"https://www.law.cornell.edu/uscode/text/26/117","by":{"2":"12"}},{"t":"usc","label":"26 U.S.C. § 132","url":"https://www.law.cornell.edu/uscode/text/26/132","by":{"2":"12"}},{"t":"usc","label":"26 U.S.C. § 3241","url":"https://www.law.cornell.edu/uscode/text/26/3241","by":{"2":"21"}},{"t":"usc","label":"45 U.S.C. § 231a","url":"https://www.law.cornell.edu/uscode/text/45/231a","subs":["(a)"],"by":{"2":"21"}},{"t":"reg","label":"20 C.F.R. § 211.2","url":"https://www.ecfr.gov/current/title-20/section-211.2","by":{"2":"9"}},{"t":"reg","label":"20 C.F.R. § 222.2","url":"https://www.ecfr.gov/current/title-20/section-222.2","by":{"2":"9"}},{"t":"reg","label":"1 Fed. Reg. 1,576","url":"https://www.govinfo.gov/link/fr/1/1576","by":{"2":"20"}},{"t":"reg","label":"13 Fed. Reg. 419","url":"https://www.govinfo.gov/link/fr/13/419","by":{"2":"9"}},{"t":"reg","label":"66 Fed. Reg. 57,023","url":"https://www.govinfo.gov/link/fr/66/57023","by":{"2":"15"}}]};